<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$history=isset($_GET['historial']);$current=$period['reporte_id']?$db->one('SELECT r.*,a.nombre FROM reportes r JOIN archivos a ON a.id=r.archivo_id WHERE r.id=?',[$period['reporte_id']]):null;
?>
<div class="page-heading"><div><h1><?=$history?'Versiones del reporte':'Reporte del cliente'?></h1><p><?=V::h(ucfirst(V::monthLabel($month)))?> · <?=$history?'Consulta las fuentes que se recibieron para este mes.':'Archivo, columnas y vista previa dentro de una misma pantalla.'?></p></div><?=$w->link($history?'Volver al reporte':'Ver versiones','reportes',['historial'=>$history?null:1])?></div>
<?php if($history):?>
<div class="action-row"><?=$w->link('+ Cargar otra versión','reportes',[],'button primary')?></div>
<?php $versions=$db->all('SELECT r.*,a.nombre,(SELECT COUNT(*) FROM reporte_filas f WHERE f.reporte_id=r.id) AS filas FROM reportes r JOIN archivos a ON a.id=r.archivo_id WHERE r.mes=? ORDER BY r.numero DESC',[$month]);if(!$versions):?><?=V::empty('Aún no hay reportes guardados','Selecciona un archivo y revisa sus columnas antes de importarlo.',$w->link('Preparar reporte','reportes',[],'button primary'))?><?php else:?>
<div class="table-wrap"><table><thead><tr><th>Versión</th><th>Archivo</th><th>Modalidad</th><th>Filas</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($versions as $version):?><tr><td>v<?=$version['numero']?><small><?=V::h($version['creado_en'])?></small></td><td><?=V::h($version['nombre'])?></td><td><?=$version['modalidad']==='detalle'?'Detalle de entregas':'Totales por sucursal'?></td><td><?=$version['filas']?></td><td><?=V::badge((int)$period['reporte_id']===(int)$version['id']?'En uso':'Anterior')?></td><td><?=$w->link('Consultar','reporte_version',['id'=>$version['id']],'text-link')?></td></tr><?php endforeach?></tbody></table></div><?php endif;return;endif?>
<form method="get" class="filters"><?=V::hidden('p','reportes')?><?=V::input('Mes','mes',$month,'month',['required'=>true])?><button class="button" type="submit">Consultar</button></form>
<?php if($current):?><div class="notice source-notice"><div><strong>Fuente en uso: v<?=$current['numero']?> · <?=V::h($current['nombre'])?></strong><p><?=$current['modalidad']==='detalle'?'Detalle de entregas':'Totales por sucursal'?>. Una carga nueva sustituye el conjunto mensual completo.</p></div><?=$w->link('Consultar','reporte_version',['id'=>$current['id']],'text-link')?></div><?php endif?>
<?php if($period['estado']==='Revisado'):?><div class="notice warning">El mes está revisado. Puedes consultar sus versiones; para cambiar la fuente, <?=$w->link('reabre el mes en Cierre mensual','cierre',[],'text-link')?>.</div><?php endif?>
<?php if(!$app->staged):?>
<form method="post" enctype="multipart/form-data" class="section-block" data-dirty><?=V::protect('reporte_cargar')?><?=V::hidden('mes',$month)?><div class="form-grid"><?=V::select('Tipo de reporte','modalidad',['detalle'=>'Detalle de entregas','totales'=>'Totales por sucursal'],V::value('modalidad','detalle'))?><label class="field"><span>Archivo recibido del cliente *</span><input type="file" name="reporte" accept=".xlsx,.csv" required><small>Excel .xlsx o CSV · hasta <?=V::h(round(Suave\Servidor::uploadLimit($db->config)/1048576,2))?> MB en este servidor.</small></label></div><div class="action-row"><button class="button primary" type="submit">Seleccionar archivo y preparar lectura</button></div></form>
<?=V::empty('Prepara el reporte antes de importarlo','Seleccionar un archivo permite revisar las hojas y columnas. La fuente en uso cambia al confirmar Importar y comparar.')?>
<div class="action-row"><span class="hint">Formatos vacíos de referencia:</span><?=$w->link('Plantilla de detalle','plantilla',['modalidad'=>'detalle'],'text-link')?><?=$w->link('Plantilla de totales','plantilla',['modalidad'=>'totales'],'text-link')?></div>
<?php else:
$file=$app->staged;$mapping=$_POST;$sheets=(new Suave\Reportes($db))->describe($file,$mapping);$preview=$app->preview;
$guess=function(array $headers,string $field):int{foreach($headers as $col=>$label){$title=Suave\OrigenReporte::key(explode('·',$label,2)[1]??'');$terms=match($field){'sucursal'=>['sucursal','código sucursal','codigo sucursal'],'fecha'=>['fecha','fecha entrega'],'folio'=>['folio','nota','remisión','remision'],'importe'=>['importe nota','importe de nota','importe','total','venta'],default=>[]};if(in_array($title,$terms,true))return (int)$col;}return 0;};
?>
<form method="post" data-dirty><?=V::protect('reporte_previsualizar')?><?=V::hidden('mes',$month)?><?=V::hidden('_stage',$file['temporal'])?>
<div class="file-heading"><?=V::icon('reportes')?><strong><?=V::h($file['nombre'])?></strong><span class="hint"><?=number_format($file['bytes']/1024,1)?> KB</span></div>
<div class="form-grid three"><?=V::select('Tipo de reporte','modalidad',['detalle'=>'Detalle de entregas','totales'=>'Totales por sucursal'],$mapping['modalidad']??'detalle')?><?=V::select('Separador decimal','decimal',['.'=>'Punto: 1,234.56',','=>'Coma: 1.234,56'],$mapping['decimal']??'.')?><?=V::select('Formato de fechas de texto','formato_fecha',['d/m/Y'=>'Día/mes/año: 15/10/2026','m/d/Y'=>'Mes/día/año: 10/15/2026','Y-m-d'=>'Año-mes-día: 2026-10-15','es-larga'=>'Español: jueves, octubre 08, 2026'],$mapping['formato_fecha']??'d/m/Y')?></div>
<p class="hint">Para el formato de las sucursales usa Detalle de entregas y asigna IMPORTE NOTA como Importe. Deja Folio sin asignar: el importe de nota no es un identificador. Los demás campos se conservan para consulta.</p>
<?=V::check('excluir_otros_meses','Excluir filas con fecha de otros meses y mostrarlas en la vista previa.',!empty($mapping['excluir_otros_meses']))?>
<?php if($file['extension']==='csv'):?><div class="form-grid"><?=V::select('Separador del CSV','delimitador',[';'=>'Punto y coma',','=>'Coma',"\t"=>'Tabulador'],$mapping['delimitador']??';')?><?=V::select('Codificación del CSV','codificacion',['UTF-8'=>'UTF-8','Windows-1252'=>'Windows-1252'],$mapping['codificacion']??'UTF-8')?></div><?php endif?>
<?php foreach($sheets as $sheet):$i=$sheet['indice'];$map=$mapping['hojas'][$i]??[];$prefix='hojas['.$i.']';$columns=[0=>'Sin asignar']+$sheet['encabezados'];$fixed=[''=>'Usar columna Sucursal'];foreach($allBranches as $b)$fixed[$b['codigo']]=$b['codigo'].' · '.$b['nombre']; ?>
<section class="sheet-card"><div class="section-heading"><h2>Hoja: <?=V::h($sheet['nombre'])?></h2><?=V::check($prefix.'[usar]','Incluir esta hoja',isset($mapping['hojas'])?!empty($map['usar']):$i===0)?></div>
<div class="form-grid three"><?=V::input('Fila de encabezados',$prefix.'[encabezado]',$map['encabezado']??1,'number',['min'=>1,'max'=>100])?><?=V::input('Última fila (opcional)',$prefix.'[ultima]',$map['ultima']??'','number',['min'=>2,'max'=>$sheet['filas'],'placeholder'=>'Hasta el final'])?><?=V::select('Sucursal por hoja',$prefix.'[sucursal_fija]',$fixed,$map['sucursal_fija']??'')?></div>
<div class="form-grid four"><?php foreach(['sucursal'=>'Columna Sucursal','fecha'=>'Columna Fecha (detalle)','importe'=>'Columna Importe','folio'=>'Columna Folio (opcional)'] as $field=>$label):?><?=V::select($label,$prefix.'['.$field.']',$columns,$map[$field]??$guess($sheet['encabezados'],$field))?><?php endforeach?></div><p class="hint">Las columnas se leen después del encabezado. Si cambias el encabezado o el separador del CSV, pulsa Revisar lectura para actualizar las columnas.</p></section>
<?php endforeach?>
<div class="action-row"><button class="button" type="submit" name="action" value="reporte_previsualizar">Revisar lectura y vista previa</button></div>
<?php if($preview):?>
<section class="section-block"><div class="section-heading"><h2><?=count($preview['filas'])?> filas válidas · <?=count($preview['errores'])?> errores</h2><strong>Total <?=N::currency($preview['total'])?></strong></div>
<?php if($preview['errores']):?><div class="notice error"><strong>No se guardará un conjunto parcial.</strong><ul><?php foreach(array_slice($preview['errores'],0,50) as $error):?><li><?=V::h($error)?></li><?php endforeach?></ul><?php if(count($preview['errores'])>50):?><p>Se muestran los primeros 50 errores.</p><?php endif?></div><?php endif?>
<?php if($preview['repetidas']):?><div class="notice warning"><strong>Posibles filas repetidas</strong><ul><?php foreach(array_slice($preview['repetidas'],0,15) as $repeat):?><li><?=V::h($repeat)?></li><?php endforeach?></ul><?=V::check('repetidas_confirmadas','Comprobé que las filas repetidas representan operaciones reales distintas.',!empty($mapping['repetidas_confirmadas']))?></div><?php endif?>
<?php if($preview['excluidas']):?><div class="notice warning"><strong><?=count($preview['excluidas'])?> filas de otros meses excluidas por tu selección.</strong><p>Revisa que el conjunto incluya todas las operaciones del mes. El archivo original completo se conserva.</p><ul><?php foreach(array_slice($preview['excluidas'],0,20) as $excluded):?><li><?=V::h($excluded['hoja'].' · fila '.$excluded['fila'].' · '.$excluded['fecha'])?></li><?php endforeach?></ul></div><?php endif?>
<?php if($preview['faltantes']):?><p class="hint">Sucursales sin filas en esta lectura: <?=V::h(implode(', ',$preview['faltantes']))?>. Su cobertura o ausencia debe documentarse antes de cerrar el mes.</p><?php endif?>
<div class="table-wrap"><table><thead><tr><th>Hoja y fila</th><th>Sucursal</th><th>Fecha</th><th>Folio</th><th>Importe</th><th>Datos recibidos</th></tr></thead><tbody><?php foreach(array_slice($preview['filas'],0,100) as $r):?><tr class="report-source-row"><td><?=V::h($r['hoja'].' · '.$r['fila'])?></td><td><?=V::h($r['sucursal_codigo'])?></td><td><?=$r['fecha']?V::date($r['fecha']):'No disponible'?></td><td><?=V::h($r['folio']?:'Sin folio')?></td><td><?=N::currency($r['importe_centavos'])?></td><td><?php include __DIR__.'/_reporte_origen.php';?></td></tr><?php endforeach?></tbody></table></div><p class="hint">Vista previa de hasta 100 filas. Al importar se validan nuevamente todas las filas seleccionadas.</p></section>
<?php endif?>
<div class="action-row spread form-actions"><?=$w->link('Cancelar preparación','reportes')?><button class="button primary" type="submit" name="action" value="reporte_importar" <?=(!$preview||$preview['errores']||$period['estado']==='Revisado')?'disabled':''?>>Importar y comparar</button></div>
</form><?php endif?>
